  'نطاق مخصص': { he: 'דומיין מותאם', en: 'Custom domain' },
  'علامة بيضاء': { he: 'מיתוג לבן', en: 'White label' },
  'بيتفعّل رقم واتساب تلقائياً بعد الاشتراك.': { he: 'מספר וואטסאפ מופעל אוטומטית לאחר ההרשמה.', en: 'A WhatsApp number is provisioned automatically after subscribing.' },
  'لوحة التحكم بس — ربط رقم واتساب بيحتاج ترقية أو تفعيل يدوي.': { he: 'לוח הבקרה בלבד — חיבור מספר וואטסאפ דורש שדרוג או הפעלה ידנית.', en: 'Dashboard only — linking a WhatsApp number needs an upgrade or manual activation.' },
  'ابدأ بهالباقة': { he: 'התחילו עם החבילה הזו', en: 'Start with this plan' },
  'أنشئ حساب شركتك': { he: 'פתחו חשבון לעסק שלכם', en: 'Create your business account' },
  'بياناتك': { he: 'הפרטים שלכם', en: 'Your details' },
